// ── STAR story validator — checks structure completeness ─────────
function validateSTAR(story) {
  const issues = [];
  if (!story.situation || story.situation.split(' ').length < 10)
    issues.push('Situation too thin — add context (team size, timeline, stakes).');
  if (!story.task || !story.task.toLowerCase().includes('i '))
    issues.push('Task must describe YOUR responsibility, not the team\'s.');
  if (!story.action || story.action.split(' ').length < 40)
    issues.push('Action too short — explain your step-by-step reasoning.');
  if (!/\d/.test(story.result))
    issues.push('Result lacks numbers — add %, $, days saved, or users impacted.');
  return issues.length === 0
    ? { valid: true, message: 'Story structure looks solid.' }
    : { valid: false, issues };
}

const weak = {
  situation: 'We had a project.',
  task: 'The team needed to finish it.',
  action: 'We worked together.',
  result: 'It went well.',
};
console.log(validateSTAR(weak));
// issues: Situation too thin, Task must describe YOUR..., Action too short, Result lacks numbers

const strong = {
  situation: 'At Acme, our 4-person backend team owned a payment API used by 200K transactions daily. Six weeks before the holiday peak, a performance regression appeared.',
  task: 'I was the on-call engineer responsible for diagnosing and resolving it before traffic spiked.',
  action: 'I profiled the hot path with Node\'s built-in profiler to rule out application code, then examined recent query plans. A missing index on order_status caused full-table scans. I deployed the index with CONCURRENTLY to avoid table locks and timed the migration at the lowest-traffic window.',
  result: 'P95 latency dropped from 1.2s to 180ms — a 85% reduction. We handled holiday traffic without downtime. I added a query-plan regression check to CI to catch this class of issue automatically.',
};
console.log(validateSTAR(strong)); // { valid: true }

// ── Common red flags — patterns that quietly sink candidates ─────

// RED FLAG 1: Using 'we' throughout the Action
// Bad:  'We decided to refactor the service and we deployed it.'
// Good: 'I proposed the refactor in the sprint planning, drafted the
//        migration plan, and led the two-day implementation sprint.'

// RED FLAG 2: No quantified result
// Bad:  'The project was a success and everyone was happy.'
// Good: 'Delivery time dropped by 30%, NPS rose 12 points.'

// RED FLAG 3: Blaming others in conflict stories
// Bad:  'My manager was wrong and I had to work around them.'
// Good: 'We had different priorities. I scheduled a 1:1, shared
//        the user data that informed my view, and we aligned on\n//        a compromise that shipped in week 3.'

// RED FLAG 4: The story has no tension
// Bad:  'I built the feature and it worked.'
// Good: 'Halfway through, the third-party API we depended on\n//        deprecated our endpoint. I had 48 hours to find an\n//        alternative, migrate our data pipeline, and retest.'

// RED FLAG 5: 'Tell me about yourself' becomes a full CV recital
// Bad:  5-minute chronological history of every job.
// Good: Present → Past → Future: 'I currently lead backend\n//       infrastructure at Acme, where I own our payments platform\n//       (present). I joined from a startup where I built the\n//       original API from zero to 10M users (past). I am looking\n//       for a senior role at scale because I want to solve\n//       distributed systems challenges — which is exactly what\n//       this role offers (future).'

console.log('Pattern review complete — no code to run.');
